def _parse_coverage(df: pd.DataFrame, fmt: str) -> dict[str, Any]:
    """Describe only fee columns actually read by the selected native parser."""
    columns = list(map(str, df.columns))
    fees = {
        "tonghuashun": ("手续费", "印花税", "过户费"),
        "eastmoney": ("佣金", "印花税"),
        "futu": ("Commission", "Platform Fee"),
    }
    if fmt == "generic":
        colmap = {str(column).strip().lower(): str(column) for column in df.columns}
        recognized = next(([colmap[key]] for key in ("fee", "commission", "fees") if key in colmap), [])
    else:
        recognized = [column for column in fees.get(fmt, ()) if column in columns]
    return {"source_rows": len(df), "raw_columns": columns,
            "recognized_fee_columns": recognized, "fee_columns_present": bool(recognized)}


